"""Run the inert controls generated by build-controls.py against this checkout."""
import argparse
import json
from pathlib import Path
import subprocess
import sys

ROOT = Path(__file__).resolve().parents[3]
HERE = Path(__file__).parent


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--cleave', default='cleave')
    args = parser.parse_args()
    subprocess.run([sys.executable, str(HERE/'build-controls.py'), '--output', str(args.output)], check=True)
    result = subprocess.run([args.cleave, '--traits-dir', str(ROOT), '--disable',
                             'radare2,third-party', '--format', 'json', 'analyze', str(args.output)],
                            capture_output=True, text=True, check=True, timeout=240)
    # Directory scans emit successive JSON reports, sometimes without newlines.
    decoder = json.JSONDecoder()
    pending = result.stdout
    files = {}
    while pending.strip():
        report, end = decoder.raw_decode(pending.lstrip())
        pending = pending.lstrip()[end:]
        files.update({f['path']:f for f in report.get('files', [])})
    outcomes = []
    for case in json.loads((args.output/'cases.json').read_text())['fixtures']:
        traits = {t['id']:t for t in files[case['path']].get('traits', [])}
        errors = [x for x in case['matched'] if x not in traits]
        errors += [x for x in case['not_matched'] if x in traits]
        assert not errors, (case['path'], errors)
        if case['path'].endswith('inert-http-file-com-imports.exe'):
            assert not any(t['crit'] >= 4 for t in traits.values())
        outcomes.append({'case':Path(case['path']).name, 'passed':True})
    (args.output/'results.json').write_text(json.dumps(outcomes, indent=2)+'\n')
    print(f'{len(outcomes)} static controls passed')


if __name__ == '__main__':
    main()
